# app.R
library(shiny)
library(bslib)
library(ggplot2)
library(dplyr)
library(readr)

# Define custom bslib theme
my_theme <- bs_theme(
  version = 5,
  bootswatch = "flatly",
  primary = "#2C3E50",
  secondary = "#18BC9C"
)

ui <- page_navbar(
  title = "Central Limit Theorem Explorer",
  theme = my_theme,
  
  sidebar = sidebar(
    width = 320,
    selectInput("dist", "Population Distribution:",
                choices = c("Normal", "Uniform", "Exponential (Skewed)", "Bimodal", "Custom Upload")),
    
    # Conditional Parameter Panels
    conditionalPanel(
      condition = "input.dist == 'Normal'",
      numericInput("norm_mean", "Mean (\U003BC):", value = 50),
      numericInput("norm_sd", "Standard Deviation (\U03C3):", value = 10, min = 0.1)
    ),
    conditionalPanel(
      condition = "input.dist == 'Uniform'",
      numericInput("unif_min", "Minimum:", value = 0),
      numericInput("unif_max", "Maximum:", value = 100)
    ),
    conditionalPanel(
      condition = "input.dist == 'Exponential (Skewed)'",
      numericInput("exp_rate", "Rate (\U03BB):", value = 0.1, min = 0.001)
    ),
    conditionalPanel(
      condition = "input.dist == 'Bimodal'",
      numericInput("bi_mean1", "Peak 1 Mean:", value = 30),
      numericInput("bi_sd1", "Peak 1 SD:", value = 5, min = 0.1),
      numericInput("bi_mean2", "Peak 2 Mean:", value = 70),
      numericInput("bi_sd2", "Peak 2 SD:", value = 5, min = 0.1)
    ),
    conditionalPanel(
      condition = "input.dist == 'Custom Upload'",
      fileInput("file1", "Choose CSV File", accept = c(".csv")),
      uiOutput("var_select")
    ),
    
    hr(),
    sliderInput("n", "Sample Size (n):", min = 2, max = 200, value = 30, step = 1),
    
    hr(),
    h5("Sampling Controls"),
    
    # NEW: Batched Animation Speed Control
    selectInput("anim_speed", "Animation Speed:", 
                choices = list("Standard (1 / sec)" = "standard", 
                               "Fast (10 / sec)" = "fast",
                               "Turbo (100 / sec)" = "turbo",
                               "Max (1,000 / sec)" = "max"), 
                selected = "fast"),
    
    layout_columns(
      actionButton("step", "Draw 1", class = "btn-info"),
      actionButton("toggle_anim", "Auto-Animate", icon = icon("play"), class = "btn-warning")
    ),
    layout_columns(
      actionButton("draw_100", "Draw 100", class = "btn-primary"),
      actionButton("draw_10k", "Draw 10,000", class = "btn-primary")
    ),
    br(),
    actionButton("reset", "Reset Samples", class = "btn-danger", width = "100%")
  ),
  
  nav_panel("Simulation",
            layout_columns(
              card(
                card_header("1. Population Distribution"),
                plotOutput("pop_plot", height = "400px")
              ),
              card(
                card_header("2. Latest Sample Drawn"),
                plotOutput("sample_plot", height = "400px")
              ),
              card(
                card_header("3. Sampling Distribution"),
                plotOutput("sampling_plot", height = "400px")
              )
            ),
            layout_columns(
              value_box(
                title = "Theoretical \U003BC",
                value = textOutput("theo_mean"),
                theme = "primary"
              ),
              value_box(
                title = "Empirical Mean of Means (\U003BC_x\U0304)",
                value = textOutput("emp_mean"),
                theme = "secondary"
              ),
              value_box(
                title = "Theoretical SE (\U03C3/\U221An)",
                value = textOutput("theo_se"),
                theme = "primary"
              ),
              value_box(
                title = "Empirical SE (s_x\U0304)",
                value = textOutput("emp_se"),
                theme = "secondary"
              )
            )
  )
)

server <- function(input, output, session) {
  
  rv <- reactiveValues(
    means = numeric(),
    current_sample = numeric(),
    animating = FALSE
  )
  
  # --- HELPER FUNCTIONS ---
  
  pop_data <- reactive({
    if (input$dist == "Normal") {
      rnorm(100000, input$norm_mean, input$norm_sd)
    } else if (input$dist == "Uniform") {
      runif(100000, input$unif_min, input$unif_max)
    } else if (input$dist == "Exponential (Skewed)") {
      rexp(100000, rate = input$exp_rate)
    } else if (input$dist == "Bimodal") {
      c(rnorm(50000, input$bi_mean1, input$bi_sd1), 
        rnorm(50000, input$bi_mean2, input$bi_sd2))
    } else if (input$dist == "Custom Upload" && !is.null(input$selected_var)) {
      req(user_data(), input$selected_var)
      na.omit(user_data()[[input$selected_var]])
    } else {
      rnorm(100000, 50, 10) 
    }
  })
  
  draw_single_sample <- function() {
    sample(pop_data(), size = input$n, replace = TRUE)
  }
  
  draw_multiple_samples <- function(n_sims) {
    n_size <- input$n
    pop <- pop_data()
    bulk_samples <- sample(pop, size = n_sims * n_size, replace = TRUE)
    samp_matrix <- matrix(bulk_samples, nrow = n_sims, ncol = n_size)
    new_means <- rowMeans(samp_matrix)
    
    rv$means <- c(rv$means, new_means)
    rv$current_sample <- samp_matrix[n_sims, ] 
  }
  
  # --- HIGH SPEED BATCHED ANIMATION LOOP ---
  
  observe({
    if (rv$animating) {
      speed <- input$anim_speed
      
      # Determine loop delay (ms) and batch size per tick
      if (speed == "standard") {
        invalidateLater(1000, session)
        batch <- 1
      } else if (speed == "fast") {
        invalidateLater(100, session)
        batch <- 1
      } else if (speed == "turbo") {
        invalidateLater(50, session) # Runs ~20 times per second
        batch <- 5                   # 20 * 5 = 100 samples/sec
      } else if (speed == "max") {
        invalidateLater(50, session) # Runs ~20 times per second
        batch <- 50                  # 20 * 50 = 1,000 samples/sec
      }
      
      isolate({
        if (batch == 1) {
          new_sample <- draw_single_sample()
          rv$current_sample <- new_sample
          rv$means <- c(rv$means, mean(new_sample))
        } else {
          draw_multiple_samples(batch)
        }
      })
    }
  })
  
  # --- BUTTON OBSERVERS ---
  
  observeEvent(input$toggle_anim, {
    rv$animating <- !rv$animating
    if(rv$animating) {
      updateActionButton(session, "toggle_anim", label = "Pause Animation", icon = icon("pause"))
    } else {
      updateActionButton(session, "toggle_anim", label = "Auto-Animate", icon = icon("play"))
    }
  })
  
  observeEvent(input$reset, {
    rv$animating <- FALSE
    updateActionButton(session, "toggle_anim", label = "Auto-Animate", icon = icon("play"))
    rv$means <- numeric()
    rv$current_sample <- numeric()
  })
  
  observeEvent(input$step, {
    new_sample <- draw_single_sample()
    rv$current_sample <- new_sample
    rv$means <- c(rv$means, mean(new_sample))
  })
  
  observeEvent(input$draw_100, { draw_multiple_samples(100) })
  observeEvent(input$draw_10k, { draw_multiple_samples(10000) })
  
  observeEvent(c(
    input$dist, input$n, input$norm_mean, input$norm_sd, 
    input$unif_min, input$unif_max, input$exp_rate, 
    input$bi_mean1, input$bi_sd1, input$bi_mean2, input$bi_sd2
  ), {
    rv$animating <- FALSE
    updateActionButton(session, "toggle_anim", label = "Auto-Animate", icon = icon("play"))
    rv$means <- numeric()
    rv$current_sample <- numeric()
  }, ignoreInit = TRUE)
  
  user_data <- reactive({
    req(input$file1)
    read_csv(input$file1$datapath)
  })
  
  output$var_select <- renderUI({
    req(user_data())
    selectInput("selected_var", "Select Numeric Variable:", choices = names(select_if(user_data(), is.numeric)))
  })
  
  # --- PLOTS ---
  
  output$pop_plot <- renderPlot({
    p_data <- data.frame(x = pop_data())
    ggplot(p_data, aes(x)) +
      geom_histogram(aes(y = after_stat(density)), bins = 150, fill = "#2C3E50", color = NA) +
      theme_minimal() +
      labs(x = "Value", y = "Density") +
      theme(axis.text.y = element_blank())
  })
  
  output$sample_plot <- renderPlot({
    validate(need(length(rv$current_sample) > 0, "Click a 'Draw' button to begin."))
    s_data <- data.frame(x = rv$current_sample)
    s_mean <- mean(rv$current_sample)
    
    dyn_bins_sample <- max(10, min(30, round(sqrt(input$n) * 2)))
    
    ggplot(s_data, aes(x)) +
      geom_histogram(bins = dyn_bins_sample, fill = "#18BC9C", color = "white") +
      geom_vline(xintercept = s_mean, color = "#E74C3C", linewidth = 2) +
      theme_minimal() +
      labs(x = "Sample Values (Red line = Sample Mean)", y = "Count")
  })
  
  output$sampling_plot <- renderPlot({
    validate(need(length(rv$means) > 0, "Waiting for samples..."))
    m_data <- data.frame(means = rv$means)
    
    pop_m <- mean(pop_data())
    pop_sd <- sd(pop_data())
    theo_se <- pop_sd / sqrt(input$n)
    peak_theo_density <- dnorm(pop_m, mean = pop_m, sd = theo_se)
    
    x_lower <- pop_m - 4 * theo_se
    x_upper <- pop_m + 4 * theo_se
    if(length(rv$means) > 0) {
      x_lower <- min(x_lower, min(rv$means))
      x_upper <- max(x_upper, max(rv$means))
    }
    
    dyn_bins_means <- max(15, min(100, round(sqrt(length(rv$means)) * 1.5)))
    
    ggplot(m_data, aes(x = means)) +
      geom_histogram(aes(y = after_stat(density)), bins = dyn_bins_means, fill = "#F39C12", color = "white", alpha = 0.8) +
      stat_function(fun = dnorm, args = list(mean = pop_m, sd = theo_se), 
                    color = "#2C3E50", linewidth = 1.2, linetype = "dashed",
                    xlim = c(pop_m - 4 * theo_se, pop_m + 4 * theo_se)) + 
      theme_minimal() +
      expand_limits(y = peak_theo_density * 1.05) + 
      labs(x = "Sample Means", y = "Density", 
           title = paste("Number of samples drawn:", format(length(rv$means), big.mark = ","))) +
      coord_cartesian(xlim = c(x_lower, x_upper))
  })
  
  # --- STATISTICS ---
  
  output$theo_mean <- renderText({ round(mean(pop_data()), 3) })
  output$emp_mean <- renderText({
    if(length(rv$means) == 0) return("-")
    round(mean(rv$means), 3)
  })
  output$theo_se <- renderText({ round(sd(pop_data()) / sqrt(input$n), 3) })
  output$emp_se <- renderText({
    if(length(rv$means) < 2) return("-")
    round(sd(rv$means), 3)
  })
}

shinyApp(ui, server)
